package io.bluetape4k.graph.age.benchmark

import io.bluetape4k.graph.model.GraphEdge
import io.bluetape4k.graph.model.GraphElementId
import io.bluetape4k.graph.model.GraphVertex
import io.bluetape4k.graph.repository.GraphOperations

/**
 * 벤치마크 전용 HashMap 기반 메모이제이션 데코레이터.
 *
 * [CachingAgeGraphOperations] 위에 얇게 감싸 createVertex/createEdge 호출을
 * 단순 [HashMap] 조회 (~3-5 ns) 로 단축한다. JMH @Scope.Benchmark 는 단일 스레드이므로
 * thread-safe 할 필요가 없고, 같은 @Benchmark 인자 조합 (예: Src/Dst/KNOWS+since=2024L) 만
 * 반복되므로 eviction/TTL 도 불필요하다.
 *
 * 프로덕션용 [CachingAgeGraphOperations] 의 Caffeine getIfPresent 오버헤드 (~13-15 ns,
 * TinyLFU frequency sketch + stats recorder + drain buffer) 를 우회하는 것이 목적이다.
 * 프로덕션 코드 경로는 건드리지 않는다 (benchmark 소스 디렉터리에만 존재).
 */
class BenchmarkFastMemoizingAgeGraphOperations(
    private val delegate: GraphOperations,
): GraphOperations by delegate {

    private val vertexMap = HashMap<Pair<String, Int>, GraphVertex>(16)
    private val edgeMap = HashMap<Triple<String, String, Int>, GraphEdge>(16)

    override fun createVertex(label: String, properties: Map<String, Any?>): GraphVertex =
        vertexMap.getOrPut(label to properties.hashCode()) {
            delegate.createVertex(label, properties)
        }

    override fun createEdge(
        fromId: GraphElementId,
        toId: GraphElementId,
        label: String,
        properties: Map<String, Any?>,
    ): GraphEdge =
        edgeMap.getOrPut(Triple(fromId.value, toId.value, properties.hashCode())) {
            delegate.createEdge(fromId, toId, label, properties)
        }
}

